mouse is outside client rect        //            //    isDragging = false;        //            //    break;        //    }        //    base.WndProc(ref m);        //}     public const int WM_USER = 0x400;        public const int DL_BEGINDRAG = (WM_USER + 133);        public const int DL_DRAGGING = (WM_USER + 134);        public const int DL_DROPPED = (WM_USER + 135);        public const int DL_CANCELDRAG = (WM_USER + 136);        [StructLayout(LayoutKind.Sequential, CharSet = CharSet.Ansi)]        public struct DRAGLISTINFO {            public uint uNotification;            public IntPtr hWnd;            public CustomControls.OS.POINT ptCursor;        }        uint nMessage = 0;        protected override void WndProc(ref Message m) {            base.WndProc(ref m);            //Console.WriteLine("Sprite > WndProc > msg:{0}", m.Msg);            if (IsDragging) { //m.Msg == Win32.WM_MOUSEMOVE &&  m.Msg == Win32.WM_LBUTTONDOWN                //DRAGLISTINFO dli = (DRAGLISTINFO)Marshal.PtrToStructure(m.LParam, typeof(DRAGLISTINFO));                Console.WriteLine("Sprite > WndProc > IsDragging msg:{0}", m.Msg);                //RenderScene();                //if (dli.uNotification == DL_DRAGGING) {                //    Console.WriteLine("Sprite > WndProc > msg DL_DRAGGING:{0}", m.Msg);                //}            }            /*const int WM_NCHITTEST = 0x84;            const int HTCLIENT = 0x1;            if (m.Msg == WM_NCHITTEST && (int)m.Result == HTCLIENT) {                m.Result = (IntPtr)Win32.HT_CAPTION;            }*/        }        [DllImport("user32.dll", CharSet = CharSet.Auto, CallingConvention = CallingConvention.StdCall)]        private static extern void mouse_event(uint dwFlags, int dx, int dy, uint cButtons, uint dwExtraInfo);        const uint MOUSEEVENTF_LEFTDOWN = 0x0002;        const uint MOUSEEVENTF_LEFTUP = 0x0004;        const uint MOUSEEVENTF_MOVE = 0x0001;        static void Drag(int startX, int startY, int endX, int endY) {            Console.WriteLine("Class > Drag > startX:{0} startY:{1} endX:{0} endY:{1}", startX, startY, endX, endY);            //endX = endX - startX;            //endY = endY - startY;            //SetCursorPos(startX, startY);            //mouse_event(MOUSEEVENTF_LEFTDOWN, 0, 0, 0, 0);            //mouse_event(MOUSEEVENTF_MOVE, endX, endY, 0, 0);            //mouse_event(MOUSEEVENTF_LEFTUP, 0, 0, 0, 0);        }        protected override void OnMouseMove(MouseEventArgs e) {            base.OnMouseMove(e);            if (e.Button == MouseButtons.Left) {                //Console.WriteLine("Sprite > OnMouseMove > drag:{0}", new Point(e.X, e.Y));                if (!IsDragging) {                    var MouseEnd = new Point(e.X, e.Y);                    if (MouseStart.DistanceTo(MouseEnd) > 10) {                        IsDragging = true;                        OnDragStart();                        // Releasing the mouse capture to allow the form to receive the order                        User32.ReleaseCapture();                        // Simulating left mouse button clicking on the title bar                        User32.SendMessage(Handle,                            Win32.WM_NCLBUTTONDOWN,  // Simulating the click                            Win32.HT_CAPTION,        // Attaching it to the title bar                            0                        // No further options required                        );                    }                    if (IScene.SnapEnabled && SnapEnabled) Snap();                    IsDragging = false;                    OnDragStop();                    //RenderScene();                }                IUGlobal.IMainForm.RefreshPropertyGrid();            }        }